const places={dhaka:{lat:23.8103,lng:90.4125,name:'ঢাকা'},mirpur:{lat:23.8069,lng:90.3687,name:'মিরপুর'},dhanmondi:{lat:23.7461,lng:90.3742,name:'ধানমন্ডি'},uttara:{lat:23.8759,lng:90.3795,name:'উত্তরা'}};
const $=s=>document.querySelector(s);let category='all',selectedWorker=null;let bookings=[];try{bookings=JSON.parse(localStorage.getItem('mishtry-bookings')||'[]');if(!Array.isArray(bookings))bookings=[]}catch{bookings=[]}
function distance(w,p){const r=Math.PI/180,a=Math.sin((w.lat-p.lat)*r/2)**2+Math.cos(w.lat*r)*Math.cos(p.lat*r)*Math.sin((w.lng-p.lng)*r/2)**2;return Math.max(.2,6371*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a)))}
function escapeHTML(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function render(){const place=places[$('#location').value],q=$('#query').value.trim().toLowerCase(),radius=+$('#radius').value;let list=workers.map(w=>({...w,distance:distance(w,place)})).filter(w=>(category==='all'||w.cat===category)&&(!$('#available').checked||w.available)&&w.distance<=radius&&(!q||[w.name,w.keywords,...w.skills].join(' ').toLowerCase().includes(q)));list.sort((a,b)=>$('#sort').value==='rate'?a.rate-b.rate:$('#sort').value==='rating'?b.rating-a.rating:a.distance-b.distance);$('#result-count').textContent=bn(list.length);$('#result-summary').textContent=`${place.name} থেকে ${bn(radius)} কিমির মধ্যে · সব প্রোফাইল নমুনা`;$('#workers').innerHTML=list.length?list.map(w=>`<article class="worker-card"><div class="card-top"><div class="avatar" style="--avatar:${w.color}" aria-hidden="true">${w.initial}</div><div><h3>${escapeHTML(w.name)}</h3><small>⌖ ${w.area} · ${bn(w.distance.toFixed(1))} কিমি দূরে</small></div></div><span class="status ${w.available?'':'busy'}">● ${w.available?'আজই উপলব্ধ':'আগামীকাল উপলব্ধ'} · ডেমো</span><p class="bio">${w.bio}</p><div class="tags">${w.skills.map(s=>`<span>${s}</span>`).join('')}</div><div class="review"><span class="gold">★</span><strong>${bn(w.rating)}</strong><span>(${bn(w.reviews)} ডেমো রিভিউ)</span><span class="verification">যাচাই করা হয়নি</span></div><div class="card-bottom"><div class="price"><strong>৳${bn(w.rate)}</strong> <small>থেকে / কাজ</small></div><button class="profile-btn" data-profile="${w.id}">প্রোফাইল দেখুন ↗</button></div></article>`).join(''):`<div class="empty"><h3>এই ফিল্টারে কোনো নমুনা কর্মী নেই</h3><p>দূরত্ব বাড়ান বা অন্য দক্ষতা বেছে নিন।</p><button class="outline" id="reset">সব ফিল্টার মুছুন</button></div>`;$('#booking-count').textContent=bn(bookings.length)}
function show(html){$('#modal-content').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}
function profile(id){selectedWorker=workers.find(w=>w.id===id);const w=selectedWorker;show(`<div class="eyebrow">নমুনা কর্মীর প্রোফাইল</div><h2>${escapeHTML(w.name)}</h2><p>⌖ ${w.area} · ${w.available?'আজই উপলব্ধ':'আগামীকাল উপলব্ধ'}</p><div class="tags">${w.skills.map(s=>`<span>${s}</span>`).join('')}</div><p>${w.bio}</p><h3>আনুমানিক রেট ৳${bn(w.rate)} থেকে</h3><p>শ্রমের প্রাথমিক রেট। যাতায়াত ও যন্ত্রাংশসহ চূড়ান্ত মূল্য কাজ বুঝে আলোচনা করতে হবে।</p><div class="notice">পরিচয় ও পেশাগত দক্ষতা যাচাই করা হয়নি। ভবিষ্যতে পরিচয়পত্র, দক্ষতার প্রমাণ এবং ম্যানুয়াল যাচাই যুক্ত হবে।</div><h3>★ ${bn(w.rating)} · নমুনা রিভিউ</h3><div class="review-box">“${w.review}”<br><small>ডেমো গ্রাহক · বাস্তব অভিজ্ঞতা নয়</small></div><button class="primary full" id="hire">কাজের অনুরোধ তৈরি করুন →</button><button class="outline full" id="contact">যোগাযোগের ডেমো দেখুন</button>`)}
function bookingForm(){const w=selectedWorker;const local=new Date();local.setMinutes(local.getMinutes()-local.getTimezoneOffset());const today=local.toISOString().slice(0,10);show(`<div class="eyebrow">ডেমো কাজের অনুরোধ</div><h2>${escapeHTML(w.name)}-কে কাজ দিন</h2><form id="hire-form"><label>কী কাজ করাতে চান?<textarea name="details" required minlength="5" maxlength="500" placeholder="যেমন: মূল দরজায় একটি ডোর ক্লোজার লাগাতে হবে"></textarea></label><label>এলাকা / কাছের পরিচিত স্থান<input name="area" required maxlength="120" placeholder="শুধু নমুনা ঠিকানা লিখুন"></label><label>পছন্দের দিন<input type="date" name="date" min="${today}" value="${today}" required></label><label>পছন্দের সময়<select name="time"><option>সকাল ৯টা–১২টা</option><option>দুপুর ১২টা–৪টা</option><option>বিকাল ৪টা–৭টা</option></select></label><div class="notice">অনুরোধ শুধু এই ব্রাউজারে সংরক্ষিত হবে। কোনো কর্মীর কাছে পাঠানো হবে না। সংবেদনশীল বা ব্যক্তিগত তথ্য লিখবেন না।</div><button class="primary full" type="submit">ডেমো অনুরোধ সংরক্ষণ করুন →</button></form>`)}
function saveBooking(form){const data=new FormData(form),b={id:Date.now(),worker:selectedWorker.id,workerSnapshot:{id:selectedWorker.id,name:selectedWorker.name,rate:selectedWorker.rate},details:data.get('details'),area:data.get('area'),date:data.get('date'),time:data.get('time'),paid:false};bookings.push(b);persist();render();show(`<div class="eyebrow">✓ ডেমো অনুরোধ সংরক্ষিত</div><h2>আপনার অনুরোধ তৈরি হয়েছে</h2><p>${escapeHTML(selectedWorker.name)} · ${escapeHTML(b.date)} · ${escapeHTML(b.time)}</p><div class="notice">এটি নিশ্চিত বুকিং নয়। কর্মী কোনো বার্তা পাননি। বাস্তব সেবায় কর্মীর সম্মতি এবং চূড়ান্ত মূল্য নিশ্চিত করতে হবে।</div><button class="primary full" data-payment="${b.id}">বিকাশ পেমেন্টের ডেমো দেখুন →</button><button class="outline full" id="view-bookings">আমার ডেমো বুকিং</button>`)}
function persist(){try{localStorage.setItem('mishtry-bookings',JSON.stringify(bookings))}catch{}}
function payment(id){const b=bookings.find(x=>x.id===id);if(!b)return;const w=(workers.find(x=>x.id===b.worker)||b.workerSnapshot);if(!w)return;show(`<div class="eyebrow">পেমেন্ট প্রিভিউ</div><h2>কাজ শেষে, স্বস্তিতে পেমেন্ট</h2><div class="payment-box"><div class="bkash">bKash <small>· ডেমো</small></div><p>${escapeHTML(w.name)} · নমুনা বিল</p><h2>৳${bn(w.rate)}</h2><p>এটি প্রাথমিক রেট দিয়ে দেখানো উদাহরণ, চূড়ান্ত বিল নয়।</p></div><div class="notice">বিকাশ সংযোগ চালু নেই। এখানে কোনো টাকা কাটা হবে না। বিকাশ নম্বর, PIN বা OTP দেবেন না।</div><button class="primary full" data-pay="${b.id}" ${b.paid?'disabled':''}>${b.paid?'ডেমো সম্পন্ন হয়েছে':'টাকা ছাড়াই পেমেন্ট অনুকরণ করুন'}</button>`)}
function listBookings(){show(`<div class="eyebrow">এই ব্রাউজারে সংরক্ষিত</div><h2>আমার ডেমো বুকিং</h2>${bookings.length?bookings.map(b=>{const w=(workers.find(w=>w.id===b.worker)||b.workerSnapshot);if(!w)return '';return `<div class="booking-row"><h3>${escapeHTML(w.name)}</h3><p>${escapeHTML(b.details)}<br>${escapeHTML(b.area)} · ${escapeHTML(b.date)} · ${escapeHTML(b.time)}</p><small>${b.paid?'পেমেন্ট অনুকরণ সম্পন্ন · কোনো লেনদেন হয়নি':'অনুরোধের খসড়া · কর্মীকে পাঠানো হয়নি'}</small><button class="outline full" data-payment="${b.id}">পেমেন্ট ডেমো দেখুন</button><button class="text-btn full" data-delete="${b.id}">এই ডেমো বুকিং মুছুন</button></div>`}).join(''):'<p>এখনও কোনো অনুরোধ নেই। কর্মীর প্রোফাইল থেকে শুরু করুন।</p>'}`)}
function join(){show(`<div class="eyebrow">দক্ষতার জন্য খোলা দরজা</div><h2>একটি দক্ষতা দিয়েই শুরু করুন</h2><p>তালা লাগানো, Windows সেটআপ বা পর্দার রড—যে কাজটি ভালো পারেন, সেটিই আপনার পরিচয়।</p><form id="join-form"><label>আপনার নাম (নমুনা)<input name="name" required maxlength="70" placeholder="একটি নমুনা নাম লিখুন"></label><label>আপনার দক্ষতা<input name="skill" required maxlength="120" placeholder="যেমন: দরজার তালা লাগানো"></label><label>কাজের এলাকা<select name="area"><option>মিরপুর, ঢাকা</option><option>ধানমন্ডি, ঢাকা</option><option>উত্তরা, ঢাকা</option></select></label><div class="notice">এটি নিবন্ধনের ডেমো। কোনো অ্যাকাউন্ট বা প্রকাশ্য প্রোফাইল তৈরি হবে না। বাস্তব নিবন্ধনে পরিচয় ও দক্ষতা যাচাই লাগবে।</div><button class="primary full">নিবন্ধনের ডেমো দেখুন →</button></form>`)}
$('#search-form').addEventListener('submit',e=>{e.preventDefault();render()});['#query','#location','#radius','#available','#sort'].forEach(s=>$(s).addEventListener(s==='#query'?'input':'change',render));$('.close').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.cat){category=b.dataset.cat;document.querySelectorAll('[data-cat]').forEach(el=>{el.classList.toggle('selected',el===b);el.setAttribute('aria-pressed',el===b)});render()}if(b.dataset.profile)profile(+b.dataset.profile);if(b.dataset.payment)payment(+b.dataset.payment);if(b.dataset.pay){const booking=bookings.find(x=>x.id===+b.dataset.pay);booking.paid=true;persist();show('<div class="eyebrow">✓ ডেমো সম্পন্ন</div><h2>পেমেন্ট প্রবাহ দেখা শেষ!</h2><p>কোনো টাকা পাঠানো বা কাটা হয়নি। বাস্তব বিকাশ পেমেন্টের জন্য অনুমোদিত মার্চেন্ট সংযোগ ও সার্ভারে লেনদেন যাচাই প্রয়োজন।</p><button class="primary full" id="view-bookings">আমার ডেমো বুকিং</button>')}if(b.dataset.delete){bookings=bookings.filter(x=>x.id!==+b.dataset.delete);persist();render();listBookings()}if(b.id==='hire')bookingForm();if(b.id==='contact')show('<div class="eyebrow">যোগাযোগের ডেমো</div><h2>আগে কথা, তারপর কাজ</h2><p>বাস্তব সংস্করণে এখান থেকে কর্মীকে কল বা বার্তা দেওয়া যাবে। এই নমুনা প্রোফাইলে কোনো বাস্তব ফোন নম্বর বা চ্যাট সংযোগ নেই।</p><div class="notice">কোনো বার্তা পাঠানো হয়নি।</div><button class="primary full" id="hire">কাজের ডেমো অনুরোধ তৈরি করুন</button>');if(['bookings','view-bookings'].includes(b.id))listBookings();if(['join','join-bottom'].includes(b.id))join();if(b.id==='reset'){$('#query').value='';$('#available').checked=false;$('#radius').value='5';$('#sort').value='distance';category='all';document.querySelectorAll('[data-cat]').forEach(el=>el.classList.toggle('selected',el.dataset.cat==='all'));render()}});
document.addEventListener('submit',e=>{if(e.target.id==='hire-form'){e.preventDefault();saveBooking(e.target)}if(e.target.id==='join-form'){e.preventDefault();show('<div class="eyebrow">✓ নিবন্ধনের প্রিভিউ সম্পন্ন</div><h2>আপনার দক্ষতার জায়গা এখানেই</h2><p>ফর্মটি কীভাবে কাজ করবে তা দেখা হলো। তথ্য কোথাও পাঠানো বা সংরক্ষণ করা হয়নি। লাইভ নিবন্ধন চালু হলে পরিচয়, দক্ষতা ও প্রাপ্যতা যোগ করা যাবে।</p>')}});render();
